"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[1553],{87238:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>h,frontMatter:()=>s,metadata:()=>o,toc:()=>d});var a=n(86070),i=n(25710);const s={sidebar_position:3,title:"System Architecture"},r="System Architecture",o={id:"reference-implementation/system-architecture",title:"System Architecture",description:"The Reference Implementation is a single application \u2014 a set of REST APIs and a web UI (currently under active development). It requires a PostgreSQL database for persistent storage and a federated identity provider (IDP) for authentication. On its own, it does not sign credentials, store files, or resolve identifiers. These capabilities are provided by independent external services \u2014 a verifiable credential service, a storage service, and an identity resolver service \u2014 each running and provisioned separately.",source:"@site/docs/reference-implementation/system-architecture.md",sourceDirName:"reference-implementation",slug:"/reference-implementation/system-architecture",permalink:"/tests-untp/docs/next/reference-implementation/system-architecture",draft:!1,unlisted:!1,editUrl:"https://github.com/uncefact/tests-untp/tree/next/documentation/docs/reference-implementation/system-architecture.md",tags:[],version:"current",sidebarPosition:3,frontMatter:{sidebar_position:3,title:"System Architecture"},sidebar:"tutorialSidebar",previous:{title:"Quick Start",permalink:"/tests-untp/docs/next/reference-implementation/quick-start"},next:{title:"Authentication",permalink:"/tests-untp/docs/next/reference-implementation/authentication/"}},c={},d=[{value:"Components",id:"components",level:2},{value:"Database",id:"database",level:3},{value:"Federated IDP (Identity Provider)",id:"federated-idp-identity-provider",level:3},{value:"External Services",id:"external-services",level:3},{value:"Multi-Tenancy",id:"multi-tenancy",level:2},{value:"System Tenant",id:"system-tenant",level:3},{value:"Authentication",id:"authentication",level:2}];function l(e){const t={a:"a",h1:"h1",h2:"h2",h3:"h3",mermaid:"mermaid",p:"p",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.h1,{id:"system-architecture",children:"System Architecture"}),"\n",(0,a.jsx)(t.p,{children:"The Reference Implementation is a single application \u2014 a set of REST APIs and a web UI (currently under active development). It requires a PostgreSQL database for persistent storage and a federated identity provider (IDP) for authentication. On its own, it does not sign credentials, store files, or resolve identifiers. These capabilities are provided by independent external services \u2014 a verifiable credential service, a storage service, and an identity resolver service \u2014 each running and provisioned separately."}),"\n",(0,a.jsx)(t.p,{children:"Every component in this architecture runs independently and manages its own data. No component stores another component's data."}),"\n",(0,a.jsx)(t.h2,{id:"components",children:"Components"}),"\n",(0,a.jsxs)(t.p,{children:["The diagram below shows all of the components and their relationships. See ",(0,a.jsx)(t.a,{href:"./quick-start",children:"Quick Start"})," for how to get these running."]}),"\n",(0,a.jsx)(t.mermaid,{value:'graph TB\n    Browser["Browser"]\n    RI["Reference Implementation\\n(Web UI + REST API)"]\n    DB["Database"]\n    KC["Federated IDP"]\n\n    VC["Verifiable Credential Service"]\n    Storage["Storage Service"]\n    IDR["Identity Resolver Service"]\n\n    Browser --\x3e RI\n    RI --\x3e|"queries"| DB\n    RI --\x3e|"authentication"| KC\n    RI --\x3e VC\n    RI --\x3e Storage\n    RI --\x3e IDR'}),"\n",(0,a.jsx)(t.h3,{id:"database",children:"Database"}),"\n",(0,a.jsx)(t.p,{children:"The Reference Implementation uses a PostgreSQL database to store the information it needs to function \u2014 tenants, users, service registrations, identifier schemes, data models, render templates, and configuration. The database does not contain the data owned by external services (such as key material or credential content \u2014 those live within each service's own storage). Instead, it stores references and metadata returned from external services so that subsequent operations can find and act on them. For example, when a DID is created via the verifiable credential service, the Reference Implementation records that the DID exists, which service it was created through, and which tenant it belongs to \u2014 but the key material itself remains in the verifiable credential service."}),"\n",(0,a.jsxs)(t.p,{children:["All data in the database is scoped to a tenant; see ",(0,a.jsx)(t.a,{href:"#multi-tenancy",children:"Multi-Tenancy"})," for how isolation is enforced. See ",(0,a.jsx)(t.a,{href:"./operations/database",children:"Database"})," for provisioning and configuration."]}),"\n",(0,a.jsxs)(t.p,{children:["On startup, the Reference Implementation automatically applies database migrations, converts existing rows to the formats the current version writes, and seeds system default records (tenants, service instances, identifier schemes, data models, render templates, and more). All three steps are idempotent and can be disabled. See ",(0,a.jsx)(t.a,{href:"./operations/startup",children:"Startup"})," for the full sequence and what gets seeded."]}),"\n",(0,a.jsx)(t.h3,{id:"federated-idp-identity-provider",children:"Federated IDP (Identity Provider)"}),"\n",(0,a.jsxs)(t.p,{children:["The Reference Implementation delegates authentication to a federated identity provider rather than managing credentials directly. The IDP handles user sign-in and issues tokens that the Reference Implementation validates on each request. See ",(0,a.jsx)(t.a,{href:"./authentication",children:"Authentication"})," for how authentication works, and ",(0,a.jsx)(t.a,{href:"./authentication/idp-requirements",children:"IDP Requirements"})," for supported providers and their configuration."]}),"\n",(0,a.jsx)(t.h3,{id:"external-services",children:"External Services"}),"\n",(0,a.jsx)(t.p,{children:"The Reference Implementation requires three external services to operate. Each must be available for the system to issue, store, and resolve credentials:"}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Service"}),(0,a.jsx)(t.th,{children:"What It Does"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.a,{href:"./services/verifiable-credential-service",children:"Verifiable Credential Service"})}),(0,a.jsx)(t.td,{children:"Signs and verifies W3C Verifiable Credentials; manages DIDs and cryptographic key material"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.a,{href:"./services/storage-service",children:"Storage Service"})}),(0,a.jsx)(t.td,{children:"Stores credentials, render templates, and other binary data"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.a,{href:"./services/identity-resolver-service",children:"Identity Resolver Service"})}),(0,a.jsx)(t.td,{children:"Registers links for a given identifier so that related information, such as credentials, can be discovered"})]})]})]}),"\n",(0,a.jsxs)(t.p,{children:["Organisations can replace any service independently as they progress along the ",(0,a.jsx)(t.a,{href:"./overview#incremental-adoption",children:"adoption ramp"}),". See ",(0,a.jsx)(t.a,{href:"./services/service-architecture",children:"Service Architecture"})," for how the service registry and adapter pattern enable this."]}),"\n",(0,a.jsx)(t.h2,{id:"multi-tenancy",children:"Multi-Tenancy"}),"\n",(0,a.jsx)(t.p,{children:"The Reference Implementation is a multi-tenant system. Each organisation that operates within an instance of the Reference Implementation is represented as a tenant. A tenant is the isolation boundary. Everything a tenant creates or configures \u2014 credentials, DIDs, service registrations, render templates \u2014 is private to that tenant and invisible to all others."}),"\n",(0,a.jsxs)(t.p,{children:["Tenant isolation is enforced automatically \u2014 the authenticated user's identity is resolved from the IDP and mapped to a tenant, and every request is scoped to that tenant. Tenants cannot access each other's data. If a tenant does not yet exist for the authenticated user, it is created automatically. How this works depends on the tenant mode (open or closed) \u2014 see ",(0,a.jsx)(t.a,{href:"./authentication/tenant-modes",children:"Tenant Modes"})," for details."]}),"\n",(0,a.jsxs)(t.p,{children:["In addition to tenant-specific data, every instance of the Reference Implementation has a ",(0,a.jsx)(t.a,{href:"#system-tenant",children:"system tenant"})," that provides a shared, read-only baseline of configuration \u2014 things like core UNTP data models, identifier schemes, and default service instances. All tenants can access these system defaults, but cannot modify them. This means that new tenants are productive immediately, without needing to configure anything upfront."]}),"\n",(0,a.jsx)(t.h3,{id:"system-tenant",children:"System Tenant"}),"\n",(0,a.jsxs)(t.p,{children:["The system tenant is a special internal tenant that owns all system default records. It is created automatically during ",(0,a.jsx)(t.a,{href:"./operations/startup",children:"startup"})," via the ",(0,a.jsx)(t.a,{href:"./operations/startup#step-3-database-seed",children:"seeding process"})," and serves as the mechanism through which system-wide configuration propagates to all tenants."]}),"\n",(0,a.jsx)(t.p,{children:"Records owned by the system tenant \u2014 such as core UNTP data models, identifier schemes, registrars, and default service instances \u2014 are read-only and accessible to every tenant in the instance. This means that every tenant can immediately issue credentials against the core UNTP data models (DPP, DCC, DFR, DIA, DTE), use the built-in identifier schemes (GTIN, GLN, ABN, ACN), and use the default verifiable credential, storage, and identity resolver service instances \u2014 all without any configuration of their own."}),"\n",(0,a.jsx)(t.p,{children:"The system tenant cannot be modified by regular tenants. It exists purely to provide a shared baseline so that the system is usable out of the box. Tenants that need to customise their setup \u2014 for example, by registering their own service instances or creating their own DIDs \u2014 do so within their own tenant boundary. Tenant-level configuration \u2014 such as service instances, DIDs, and other resources \u2014 takes precedence over the system defaults when set as the active default for that tenant."}),"\n",(0,a.jsx)(t.h2,{id:"authentication",children:"Authentication"}),"\n",(0,a.jsxs)(t.p,{children:["The Reference Implementation supports two authentication methods, both backed by the federated IDP: browser sessions (via OAuth2/OIDC redirect flow) and service account access (via Bearer tokens). Most routes require authentication, though some \u2014 such as credential verification \u2014 are publicly accessible. See ",(0,a.jsx)(t.a,{href:"./authentication",children:"Authentication"})," for full details."]})]})}function h(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},25710:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>o});var a=n(30758);const i={},s=a.createContext(i);function r(e){const t=a.useContext(s);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);